        while queue:
            r, c = queue.pop(0)
            cells.append((r, c))
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if not visited[nr][nc] and original[nr][nc] == '.':
                        visited[nr][nc] = True
                        queue.append((nr, nc))

        return cells

    result = [[cell for cell in row] for row in grid]

    for i in range(n):
        for j in range(m):
            if original[i][j] == '.' and original is not None:
                visited = set()
                room = []
                stack = [(i, j)]
                while stack:
                    r, c = stack.pop()
                    if (r, c) in visited:
                        continue
                    visited.add((r, c))
                    room.append((r, c))
                    for dr, dc in dirs:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if original[nr][nc] == '.' and (nr, nc) not in visited:
                                stack.append((nr, nc))

                if not room:
                    continue
                min_r = min(r for r, c in room)
                max_r = max(r for r, c in room)
                min_c = min(c for r, c in room)
                max_c = max(c for r, c in room)

                # Check if this room is already a rectangle
                is_rect = True
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
