                    level[k] = level[v] + 1
                    queue.append(k)
        return t in level

    def dfs(v, up):
        if v == t or up == 0:
            return up
        for k in range(it[v], len(capacity[v])):
            it[v] = k
            tr, p = level, capacity
            nxt = k
            if tr[nxt][k] > 0 and level[k] == level[v] + 1:
                pushed = dfs(k, min(up, tr[nxt][k]))
                if pushed > 0:
                    tr[v][k] -= pushed
                    tr[k][nxt] += pushed
                    return pushed
        return 0

    flow = 0
