        while queue:
            v = queue.popleft()
            for k in range(len(capacity[v])):
                if capacity[v][k] > 0 and level[k] == -1:
                    level[k] = level[v] + 1
                    queue.append(k)
        return t in [i for i in range(n) if level[i] != -1]

    def dfs(v, up):
        if v == t or up == 0:
            return up
        for k in range(it[v], len(capacity[v])):
            it[v] = k
            nxt = k
            if capacity[v][nxt] > 0 and level[nxt] == level[v] + 1:
                pushed = dfs(nxt, min(up, capacity[v][nxt]))
                if pushed > 0:
                    capacity[v][nxt] -= pushed
                    capacity[nxt][v] += pushed
                    return pushed
        return 0

    flow = 0
    while bfs():
        it = [0] * n
        while True:
            pushed = dfs(s, INF)
            if pushed == 0:
