            prob += dp(i + 1, j, balance + 1) * num_remaining_10 / total_remaining

            # Add 20-euro customer (only if we have change)
            if balance > 0:
                prob += dp(i, j + 1, balance - 1) * num_remaining_20 / total_remaining

