I'll create a helper function to check validity and complete words greedily:

```python
from typing import List, Tuple

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')

    # If there are no lines, return -1
    if not lines:
        return "-1\n"

    vowels_consonants = lines[0]

    try:
        n, m = map(int, lines[1].split())
    except IndexError:
        return "-1\n"

    rules = []
    for i in range(2, 2 + m):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 4:
            pos1, t1, pos2, t2 = parts[0], parts[1], parts[2], parts[3]
            rules.append((int(pos1), t1, int(pos2), t2))

    try:
        s = lines[2 + m] if 2 + m < len(lines) else ""
    except IndexError:
        return "-1\n"

    if len(s) != n:
        return "-1\n"

    # Build type map: char -> 'V' or 'C'
    type_map = {}
    for i, t in enumerate(vowels_consonants):
        ch = chr(ord('a') + i)
        type_map[ch] = t

    def get_type(char):
        return type_map.get(char, '?')

    def is_valid(word):
        for (pos1, t1, pos2, t2) in rules:
            c1 = word[pos1 - 1]
            c2 = word[pos2 - 1]
            type1 = get_type(c1)
            type2 = get_type(c2)

            if type1 == t1 and type2 != t2:
                return False
        return True

    def try_complete(word: List[str], pos: int) -> List[str]:
        """Try to fill positions from pos to n-1 with smallest valid characters"""
        if pos >= n:
            return word[:]

        # Try each character in alphabetical order
        for c_code in range(len(vowels_consonants)):
            ch = chr(ord('a') + c_code)
            word[pos] = ch

            # Check if this single position causes any rule violation
            # that would be caught by checking forward rules
            violated = False
            for (p1, t1, p2, t2) in rules:
                idx1 = p1 - 1
                idx2 = p2 - 1

                c1 = word[idx1] if idx1 < n else '?'
                c2 = word[idx2] if idx2 < n else '?'

                type1 = get_type(c1)
                type2 = get_type(c2)

                # Rule violated if posit1 has type t1 but pos2 doesn't have type t2
                if type1 == t1 and type2 != t2:
                    violated = True
                    break

            if violated:
                continue

            # Recursively try to complete
            result = try_complete(word, pos + 1)
            if result is not None:
                return result

        return None

    # Try to find a valid word
    word_list = list(s)

    # First check if s is already valid
    if is_valid(word_list):
        return s + '\n'

    # For each position, try to make a larger character and complete the rest
    for i in range(n):
        # Save original
        original = word_list[i]

        # Try each character larger than original
        for c_code in range(ord(original) + ord('a'), ord('z') + 1):
            if ord(chr(c_code)) < ord('a') + len(vowels_consonments):
                char = chr(ord('a') + c_code - ord('a'))
                word_list[i] = char

                # Try to complete the rest and check validity
                if is_valid(word_list):
                    return ''.join(word_list) + '\n'

        # If we get here, no solution with prefix s[0:i] is valid
        # We need to try with larger prefix - impossible, so don't proceed with this position

    # If we couldn't find any valid word starting from any position
    return "-1\n"
