            if i >= j:
                continue
            for block in blocks:
                if friends[i] in block and friends[j] in block:
                    adj[i][j] = adj[j][i] = True
                    break

    # Maximum Independent Set with branch and bound
    import sys
    sys.setrecursionlimit(10000)

    deg = [sum(adj[i]) for i in range(n)]
    idx_order = sorted(range(n), key=lambda i: deg[i])
    rev_map = [0] * n
    for i, p in enumerate(idx_order):
        rev_map[p] = i

    best = 0

    def solve(current_set, mask):
        nonlocal best
        if mask == 0:
            best = max(best, len(current_set))
            return

        # Find first unprocessed vertex
        first = -1
        for i in range(n):
            if mask & (1 << i):
                first = i
                break

        if first == -1:
            best = max(best, len(current_set))
            return

        # Branch: don't include first
        next_mask = mask & ~(1 << first)
        if len(current_set) + next_mask.bit_count() > best:
            solve(current_set, next_mask)

        # Branch: include first (must remove conflicting)
        conflict_mask = 0
        for j in range(n):
            if adj[first][j]:
                conflict_mask |= (1 << j)

        solve(current_set, mask & ~conflict_mask)

    solve([], (1 << n) - 1)
    return str(best)
