```python
def solution(input_str):
    """
    Find the number of distinct integers representable with exactly n roman digits.
    Digits: I=1, V=5, X=10, L=50
    """
    n = int(input_str.strip())

    if n <= 0:
        return "0\n"

    # Use DP to track all achievable sums
    # dp_set contains all sums achievable with the current number of digits
    achievable = {0}
    digits = [1, 5, 10, 50]

    # For each digit position, add all digit values to existing achievable sums
    for _ in range(n):
        next_achievable = set()
        for s in achievable:
            for d in digits:
                next_achievable.add(s + d)
        achievable = next_achievable

    return f"{len(achievable)}\n"


