# Solution implementation
MOD = 10**9 + 7

def solution(input_str):
    """
    Process string replacement queries and return result mod 10^9 + 7

    Strategy: Process queries in reverse order to track what each digit
    eventually expands to (value and length)
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "0\n"

    s = lines[0] if len(lines) > 0 else "0"
    n = int(lines[1]) if len(lines) > 1 else 0

    queries = []
    idx = 2
    for _ in range(n):
        while idx < len(lines):
            if lines[idx].strip():
                queries.append(lines[idx])
                idx += 1
                break
            else:
                idx += 1
        else:
            break

    # Parse all queries
    parsed = []
    for q in queries:
        try:
            if '->' in q:
                d_str, t = q.split('->', 1)
                if d_str and d_str.isdigit() and len(d_str) == 1:
                    parsed.append((int(d_str), t))
        except:
            continue

    # Track what each digit (0-9) expands to
    # expansion[d] = (value, length) where value is mod MOD
    expansion = {}
    for d in range(10):
        expansion[d] = (d % MOD, 1)

    # Process queries in reverse order
    for d, t in reversed(parsed):
        new_val = 0
        new_len = 0

        for char in t:
            v = int(char)
            val, l = expansion[v]
            # Append val after new_len trailing digits
            if new_len > 0 or val != 0:
                new_val = (new_val * pow(10, l, MOD) + val) % MOD
            new_len += l

        expansion[d] = (new_val, new_len % (MOD - 1))

    # Compute result from original string
    result = 0
    for char in s:
        v = int(char)
        val, _ = expansion[v]
        result = (result * pow(10, 1, MOD) + val) % MOD

    return str(result) + '\n'
```

