from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "NO"

    adj = [[] for _ in range(n + 1)]

    for i in range(min(m, len(lines) - 1)):
        parts = list(map(int, lines[1 + i].split()))
        if len(parts) == 3:
            u, v, typ = parts[0], parts[1], parts[2]
            adj[u].append((v, typ))
            adj[v].append((u, typ))

    ans = [0.0] * (n + 1)
    visited = [False] * (n + 1)
    EPS = 1e-9

    for start in range(1, n + 1):
        if visited[start]:
            continue

        queue = [start]
        visited[start] = True
        ans[start] = 0.0

        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1

            for v, typ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    ans[v] = 1.0 - ans[u] if typ == 1 else 2.0 - ans[u]
                    queue.append(v)
                else:
                    expected = 1.0 - ans[u] if typ == 1 else 2.0 - ans[u]
                    if abs(ans[v] - expected) > EPS:
                        return "NO"

    result = "YES\n" + " ".join(f"{ans[i]:.2f}" for i in range(1, n + 1))
    return result
