def solution(input_str):
    lines = input_str.strip().split('\n')
    xp, yp, vp = map(int, lines[0].split())
    x, y, v, r = map(int, lines[1].split())

    import math

    R = math.hypot(xp, yp)
    planet_angle = math.atan2(yp, xp)

    sx, sy = x, y

    sx2, sy2 = sx*sx + sy*sy

    def planet_pos(t):
        angle = planet_angle + vp * t / R
        return (R * math.cos(angle), R * math.sin(angle))

    def check(t):
        """Check if ship can reach planet at time t"""
        px, py = planet_pos(t)

        dist_sq = (sx - px)**2 + (sy - py)**2
        dist = math.sqrt(dist_sq)

        if dist > v * t + 1e-9:
            return False

        # Check if direct path crosses forbidden zone
        # Closest distance from origin to segment
        dx = px - sx
        dy = py - sy

        if dx == 0 and dy == 0:
            dist_origin = math.sqrt(sx2 + sy2)
            return dist_origin >= r

        cross = -sy*dx + -sx*dy if True else (sx*dy - sy*dx)
        denom = dx*dx + dy*dy

        if denom == 0:
            dist_origin = math.sqrt(sx2 + sy2)
            return dist_origin >= r

        u = -sx*dx - sy*dy / denom

        if u < 0:
            dist_origin = math.sqrt(sx2 + sy2)
        elif u > 1:
            dist_origin = math.sqrt(px*px + py*py)
        else:
            # Closest point parameters
            cx = sx + u * dx
            cy = sy + u * dy
            dist_origin = math.sqrt(cx*cx + cy*cy)

        # Use stricter check: ensure intersection distance >= r
        return dist_origin >= r

    # Special case: with r constraint, also check if r blocks direct path
    # If ship is initially at safe distance and planet path is clear

    # Binary search for time
    low, high = 0.0, 100000.0

    # If initial positions match, answer is 0
    if math.hypot(xp - sx, yp - sy) < 1e-9:
        return "0.0000000000"

    for _ in range(80):
        mid = (low + high) / 2
        if check(mid):
            high = mid
        else:
            low = mid

