After analyzing the graph structure, I found that using `(2*r + c) % 4` as the color assignment gives us exactly 4 different colors where any two adjacent vertices have different colors. This is because for adjacent vertices, the difference in their (2r+c) values is always between 1 and 4, ensuring different remainders mod 4.

Here's the solution:

```python
import os

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    def get_color_index(r, c):
        return (2 * r + c) % 4

    # Check if any pre-assigned cells conflict with adjacent cells
    for r in range(n):
        for c in range(m):
            if grid[r][c] != '0':
                color = int(grid[r][c])
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] != '0':
                                if int(grid[nr][nc]) == color:
                                    return '0\n'

    # Fill in the missing cells using the pattern
    color_map = {0: 1, 1: 2, 2: 3, 3: 4}
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '0':
                grid[r][c] = str(color_map[get_color_index(r, c)])

    return '\n'.join(''.join(row) for row in grid) + '\n'
