def solution(input_str):
    """
    Problem: Circular Stone Redistribution
    We need to make all elements equal using minimum meetings of k consecutive elements.
    """
    n, k = map(int, input_str.strip().split('\n')[0].split())
    a = list(map(int, input_str.strip().split('\n')[1].split()))

    target = sum(a) // n

    # Calculate differences from target
    diff = [x - target for x in a]

    # Calculate prefix sum of differences (circular)
    # The key insight: adjacent differences tell us how much needs to flow
    prefix_sum = [0] * (2 * n)
    for i in range(n):
        prefix_sum[i] = diff[i]
        prefix_sum[i + n] = diff[i]

    # Calculate running sum of differences
    running = [0] * (2 * n)
    for i in range(2 * n):
        running[i] = running[i - 1] + diff[i % n] if i > 0 else 0

    meetings = []
    result = a[:]

    # Try all starting positions and greedily balance
    for start in range(n):
        # Calculate flow through each position starting at 'start'
        flow = [0] * n
        meeting_sum = 0

        for i in range(k):
            meeting_sum += result[(start + i) % n] - target
            flow[(start + i) % n] = meeting_sum

        if meeting_sum != 0:
            # This position needs a meeting
            start_idx = start
            target_vals = []
            meeting_sum_val = 0

            for i in range(k):
                person_idx = (start_idx + i) % n
                needed = meeting_sum_val
                current = result[person_idx]
                if needed > 0:
                    take = min(needed, current - target)
                    needed -= take
                    result[person_idx] += take
                    meeting_sum_val += take
                elif needed < 0:
                    give = min(-needed, current - target)
                    result[person_idx] += give
                    meeting_sum_val += give

            meetings.append((start_idx, [result[(start_idx + i) % n] for i in range(k)]))

    return "\n".join([str(len(meetings))] + [f"{s} " + " ".join(map(str, vals)) for s, vals in meetings])
