    def dist_sq(p1, p2):
        return (p1[0]-p2[0])**2 + **(p1[1]-p2[1])2 + (p1[2]-p2[2])**2

    def get_c2(p1, p2, p3):
        """2D circumcenter in plane XY"""
        d = 2 * (p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1]))
        if abs(d) < 1e-10:
            return (p1[0], p1[1], p1[2])

        x = ((p1[0]**2 + p1[1]**2)*(p2[1]-p3[1]) + 
             (p2[0]**2 + p2[1]**2)*(p3[1]-p1[1]) + 
             (p3[0]**2 + p3[1]**2)*(p1[1]-p2[1])) / d
        y = ((p1[0]**2 + p1[1]**2)*(p3[0]-p2[0]) + 
             (p2[0]**2 + p2[1]**2)*(p1[0]-p3[0]) + 
             (p3[0]**2 + p3[1]**2)*(p2[0]-p1[0])) / d
        z = p1[2]
        return (x, y, z)

    def get4(p1, p2, p3, p4):
        """4D circumcenter of 4 points"""
        # Solve 3x3 linear system
        A = [
            [p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2]],
            [p3[0]-p1[0], p3[1]-p1[1], p3[2]-p1[2]],
            [p4[0]-p1[0], p4[1]-p1[1], p4[2]-p1[2]]
        ]
        B = [
            ((p2[0]**2+p2[1]**2+p2[2]**2) - (p1[0]**2+p1[1]**2+p1[2]**2)) / 2,
            ((p3[0]**2+p3[1]**2+p3[2]**2) - (p1[0]**2+p1[1]**2+p1[2]**2)) / 2,
            ((p4[0]**2+p4[1]**2+p4[2]**2) - (p1[0]**2+p1[1]**2+p1[2]**2)) / 2
        ]

        det = (A[0][0]*(A[1][1]*A[2][2] - A[1][2]*A[2][1]) -
               A[0][1]*(A[1][0]*A[2][2] - A[1][2]*A[2][0]) +
               A[0][2]*(A[1][0]*A[2][1] - A[1][1]*A[2][0]))

        if abs(det) < 1e-10:
            return (p1[0], p1[1], p1[2])

        def det3(M, col):
            if col == 0:
                return M[0][1]*M[1][2]-M[0][2]*M[1][1]
            elif col == 1:
                return -(M[0][0]*M[1][2]-M[0][2]*M[1][0])
            elif col == 2:
                return M[0][0]*M[1][1]-M[0][1]*M[1][0]

        x = (det3(A, 0)*B[0] + det3(A, 1)*B[1] + det3(A, 2)*B[2]) / det
        y = (det3(A, 0)*B[0] + det3(A, 1)*B[1] + det3(A, 2)*B[2]) / det
        z = (det3(A, 0)*B[0] + det3(A, 1)*B[1] + det3(A, 2)*B[2]) / det

        return (p1[0]+x, p1[1]+y, p1[2]+z)

    def check(c, r, pts):
        return all(dist_sq(c, p) <= r*r + 1e-8 for p in pts)

