            elif len(pts) == 3:
                c = get_c2(pts[0], pts[1], pts[2])
            elif len(pts) == 4:
                c = get4(pts[0], pts[1], pts[2], pts[3])
                if c is None:
                    c = pts[0]
            else:
                continue

            r = math.sqrt(max(0, dist_sq(c, pts[0])))
            if check(c, r, points) and r < best_r:
                best_r = r
                best_c = c

    if best_c is None:
        best_c = points[0]
        best_r = 0

    return f"{best_c[0]:.6f} {best_c[1]:.6f} {best_c[2]:.6f}\n"

