from collections import deque
from _solution import POTHack

def solution(input_str):
    parts = input_str.strip().split('\n')
    s = parts[0]
    t = parts[1]
    ns, nt = len(s), len(t)

    # Total counts (invariant through swaps)
    total_a = s.count('a') + t.count('a')
    total_b = ns + nt - total_a

    # Check feasible goals
    goals = []
    if total_a == ns and total_b == nt:
        goals.append(1)  # s all a's, t all b's
    if total_a == nt and total_b == ns:
        goals.append(2)  # s all b's, t all a's

    if not goals:
        return "0"

    # BFS: state is (actual_s, actual_t, path)
    # path = [(i1, j1), (i2, j2), ...] where we swapped s[:i] with t[:j]
    queue = deque([(s, t, [])])
    visited = {(s, t)}

    while queue:
        cur_s, cur_t, path = queue.popleft()

        for goal in goals:
            if goal == 1:
                # Check: cur_s all 'a's AND cur_t all 'b's
                if cur_s == 'a' * ns and cur_t == 'b' * nt:
                    # Build output
                    lines = []
                    for i, j in path:
                        lines.append(f"{i} {j}")
                    return "\n" + "\n".join(lines)
            else:
                # goal == 2: cur_s all 'b's AND cur_t all 'a's
                if cur_s == 'b' * ns and cur_t == 'a' * nt:
                    lines = []
                    for i, j in path:
                        lines.append(f"{i} {j}")
                    return "\n" + "\n".join(lines)

        # Try all possible swaps: (i, j) where 0 <= i <= ns, 0 <= j <= nt
        for i in range(ns + 1):
            for j in range(nt + 1):
                if i == 0 and j == 0:
                    continue
                # Apply swap: s with prefix i, t with prefix j
                cur_s_next = t[0:j] + s[i:]
                cur_t_next = s[0:i] + t[j:]
                state = (cur_s_next, cur_t_next)
                if state not in visited:
                    new_path = path + [(i, j)]
                    visited.add(state)
                    queue.append((cur_s_next, cur_t_next, new_path))

    return "0"
```

The solution uses BFS where states track the actual string contents after each prefix swap. The key insight is that for a valid goal:
- For goal 1: total_a must equal len(s) and total_b must equal len(t)
- For goal 2: total_a must equal len(t) and total_b must equal len(s)

The BFS explores all possible prefix swap pairs (i, j) where we swap prefix of length i from s with prefix of length j from t, until we reach a valid goal state.

