from collections import deque

def solution(input_str):
    """Find minimum subtractions to reduce number to zero using only digits present in current number."""
    n = int(input_str.strip())

    if n == 0:
        return "0\n"

    # BFS to find minimum number of operations
    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        # Get all unique non-zero digits in the current number
        digits = set(str(current)) - {'0'}

        if not digits:
            continue

        # For each digit, try subtracting it
        for d in digits:
            new_val = current - d

            # If we've reached zero
            if new_val == 0:
                return str(steps + 1) + "\n"

            # If this state hasn't been visited
            if new_val >= 0 and new_val not in visited:
                visited.add(new_val)
                queue.append((new_val, steps + 1))

    return "-1\n"

