def solution(input_data):
    """
    Solves the wire connection problem.

    Args:
        input_data: String containing test cases

    Returns:
        String with the output for all test cases
    """
    if not input_data or not input_data.strip():
        return ''

    lines = input_data.strip().split('\n')
    idx = 0

    def solve():
        nonlocal idx

        if idx >= len(lines):
            return ''

        try:
            t = int(lines[idx])
            idx += 1
        except:
            return ''

        output = []

        for _ in range(t):
            if idx >= len(lines):
                break

            try:
                n = int(lines[idx])
                idx += 1
            except:
                break

            # Read wires
            wires = []
            contact_to_wires = {}

            for i in range(n):
                if idx >= len(lines):
                    break
                parts = lines[idx].split()
                idx += 1
                x, y = int(parts[0]), int(parts[1])
                wires.append([x, y])

                if x not in contact_to_wires:
                    contact_to_wires[x] = []
                contact_to_wires[x].append(i)
                if y not in contact_to_wires:
                    contact_to_wires[y] = []
                contact_to_wires[y].append(i)

            if n == 0:
                output.append('0')
                continue

            # Single wire case
            if n == 1:
                output.append('0')
                continue

            # Union-Find on wires
            parent = list(range(n))
            def find(x):
                root = x
                while parent[root] != root:
                    root = parent[root]
                while x != root:
                    nxt = parent[x]
                    parent[x] = root
                    x = nxt
                return root

            def union(x, y):
                px, py = find(x), find(y)
                if px != py:
                    parent[px] = py

            # Union all wires sharing a contact
            for contact, wire_indices in contact_to_wires.items():
                if len(wire_indices) > 1:
                    for i in range(len(wire_indices) - 1):
                        union(wire_indices[i], wire_indices[i + 1])

            # Identify representative wire for each component
            comp_wire = {}
            for i in range(n):
                root = find(i)
                if root not in comp_wire:
                    comp_wire[root] = i

            num_components = len(comp_wire)

            if num_components == 1:
                output.append('0')
            else:
                k = num_components - 1
                output.append(str(k))

                # Connect components sequentially
                sorted_roots = sorted(comp_wire.keys())
                prev_wire_idx = comp_wire[sorted_roots[0]]

                for comp_idx in range(1, len(sorted_roots)):
